/* Finite Float64 JSON codec. Finite nonzero JSON numbers round-trip IEEE-754 doubles exactly; signed zero uses an explicit tag.
 * Typed arrays are tagged to preserve dtype and shape on raw evidence export. */
import {fail} from './validation.js';
const TYPES={Float64Array,Uint8Array,Int8Array,Int32Array};
export function encode(value){const seen=new Set();function walk(x,depth){if(depth>32)fail('CODEC_LIMIT','Export nesting too deep');if(x===null||typeof x==='string'||typeof x==='boolean')return x;if(typeof x==='number'){if(!Number.isFinite(x))fail('NONFINITE_EXPORT','Nonfinite result cannot be exported');return Object.is(x,-0)?{$number:'-0'}:x;}if(typeof x!=='object')fail('INVALID_EXPORT','Unsupported export value');if(seen.has(x))fail('INVALID_EXPORT','Cyclic export');seen.add(x);let out;if(ArrayBuffer.isView(x)){const type=x.constructor.name;if(!Object.hasOwn(TYPES,type)||!(x.buffer instanceof ArrayBuffer))fail('INVALID_EXPORT','Unsupported array');out={$typed:type,values:Array.from(x,v=>walk(v,depth+1))};}else if(Array.isArray(x))out=x.map(v=>walk(v,depth+1));else {out={};for(const k of Object.keys(x)){if(['__proto__','constructor','prototype','$number','$typed'].includes(k))fail('INVALID_EXPORT','Unsafe or reserved key');out[k]=walk(x[k],depth+1);}}seen.delete(x);return out;}return JSON.stringify({codec:'sensing-otfs-finite-typed-json-v2',value:walk(value,0)});}
export function decode(text){if(typeof text!=='string'||text.length>8*1024*1024)fail('CODEC_LIMIT','Export must be text at most 8 MiB');const root=JSON.parse(text);if(root?.codec!=='sensing-otfs-finite-typed-json-v2'||Object.keys(root).length!==2)fail('INVALID_EXPORT','Unsupported codec');let nodes=0;function walk(x,d){if(++nodes>500000||d>32)fail('CODEC_LIMIT','Import budget exceeded');if(x===null||typeof x==='string'||typeof x==='boolean')return x;if(typeof x==='number'){if(!Number.isFinite(x))fail('NONFINITE_EXPORT','Nonfinite input');return x;}if(typeof x!=='object')fail('INVALID_EXPORT','Bad value');if(Array.isArray(x))return x.map(v=>walk(v,d+1));const names=Object.keys(x);if(names.includes('$number')){if(names.length!==1||x.$number!=='-0')fail('INVALID_EXPORT','Invalid signed-zero tag');return -0;}if(names.includes('$typed')){if(names.length!==2||!Object.hasOwn(TYPES,x.$typed)||!Array.isArray(x.values)||x.values.length>10000)fail('INVALID_EXPORT','Invalid tagged array');const v=x.values.map(item=>{const v=walk(item,d+1);if(typeof v!=='number'||!Number.isFinite(v))fail('INVALID_EXPORT','Invalid typed element');return v;});const arr=new TYPES[x.$typed](v);if(v.some((value,i)=>!Object.is(value,arr[i])))fail('INVALID_EXPORT','Typed numeric conversion is lossy');return arr;}const out={};for(const k of names){if(['__proto__','constructor','prototype'].includes(k))fail('INVALID_EXPORT','Unsafe key');out[k]=walk(x[k],d+1);}return out;}return walk(root.value,0);}
export async function sha256(text){if(typeof text!=='string')fail('INVALID_INPUT','Hash text required');const subtle=globalThis.crypto?.subtle??(await import('node:crypto')).webcrypto.subtle;const digest=await subtle.digest('SHA-256',new TextEncoder().encode(text));return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');}
